const mappings = $input.all();

const env = $('Read env').first().json;

const mainTable = env.main_table;
const invoiceField = env.invoice_field;
const customerField = env.customer_field;

const selectFields = [];
const joins = new Map();

for (const item of mappings) {

  const row = item.json;

  if (row.extract_sql !== 'YES') {
    continue;
  }

  if (
    !row.table_name ||
    !row.field_name ||
    !row.functional_name
  ) {
    continue;
  }

  selectFields.push(
    `${row.table_name}.${row.field_name} AS ${row.functional_name}`
  );

  if (
    row.join_table &&
    row.join_condition &&
    row.join_table !== ''
  ) {
    joins.set(
      row.join_table,
      row.join_condition
    );
  }
}

const uniqueFields =
  [...new Set(selectFields)];

let joinSql = '';

for (const [table, condition] of joins.entries()) {

  if (table !== mainTable) {

    joinSql += `
LEFT JOIN ${table}
ON ${condition}
`;
  }
}

const invoiceId =
$('Select the bill').first().json.invoice_id;

const clientCode =
$('Select the bill').first().json.client_code;

const sql = `
SELECT
${uniqueFields.join(',\n')}

FROM ${mainTable}

${joinSql}

WHERE
${mainTable}.${invoiceField}='${invoiceId}'
AND
${mainTable}.${customerField}='${clientCode}'
`;

return [{
  json: {
    sql,
    field_count: uniqueFields.length
  }
}];

const sqlRows = $('Microsoft SQL').all();
const mappingRows = $('Mapping file').all();

const first = sqlRows[0].json;

const result = {};

function setValue(obj, path, value) {

  const keys = path.split('.');

  let current = obj;

  for (let i = 0; i < keys.length - 1; i++) {

    if (!current[keys[i]]) {
      current[keys[i]] = {};
    }

    current = current[keys[i]];
  }

  current[keys[keys.length - 1]] = value;
}


// =========================
// HEADER FIELDS
// =========================

for (const m of mappingRows) {

  const map = m.json;

  if (map.source_type === 'LINE') {
    continue;
  }

  if (map.table_name === 'CALC') {
    continue;
  }

  const value = first[map.functional_name];

  if (value !== undefined) {

    setValue(
      result,
      map.json_path,
      value
    );

  }

}


// =========================
// CALCULATED HEADER FIELDS
// =========================

const vat_amount =
  Number(first.total_ttc || 0)
  -
  Number(first.taxable_amount || 0);

const net_amount =
  Number(first.total_ht || 0)
  +
  vat_amount;

const gross_amount =
  Number(first.taxable_amount || 0)
  +
  vat_amount;

setValue(
  result,
  'totals.vat_amount',
  vat_amount
);

setValue(
  result,
  'totals.net_amount',
  net_amount
);

setValue(
  result,
  'totals.gross_amount',
  gross_amount
);


// =========================
// LINES
// =========================

result.lines = [];

const seen = new Set();

for (const row of sqlRows) {

  const key =
    `${row.json.reference}_${row.json.designation}`;

  if (seen.has(key)) {
    continue;
  }

  seen.add(key);

  const quantity =
    Number(row.json.quantity || 0);

  const unit_price =
    Number(row.json.unit_price || 0);

  const line_total_ht =
    Number(row.json.line_total_ht || 0);

  result.lines.push({

    reference:
      row.json.reference,

    designation:
      row.json.designation,

    quantity,

    unit_price,

    line_total_ht,

    tax_rate:
      row.json.tax_rate,

    vat_code:
      row.json.vat_code,

    discount:
      row.json.discount,

    article_variant:
      row.json.article_variant,

    line_total_calculated:
      quantity * unit_price,

    discount_amount:
      (quantity * unit_price)
      - line_total_ht

  });

}


// =========================
// FULL ADDRESS
// =========================

if (result.customer) {

  result.customer.full_address = [
    result.customer.address,
    result.customer.address2,
    result.customer.city,
    result.customer.postal_code
  ]
  .filter(Boolean)
  .join(' ');
}

if (result.supplier) {

  result.supplier.full_address = [
    result.supplier.address,
    result.supplier.address2,
    result.supplier.city,
    result.supplier.postal_code
  ]
  .filter(Boolean)
  .join(' ');
}


// =========================
// PAYMENT DESCRIPTION
// =========================

if (result.payment) {

  result.payment.description = [
    result.payment.type,
    result.payment.code
  ]
  .filter(Boolean)
  .join(' ');
}


// =========================
// RETURN
// =========================

return [{
  json: result
}];

const rows = $input.all();

const env = {};

for (const row of rows) {

  env[row.json.parameter] =
  row.json.value;

}

return [{
  json: env
}];

// Nœud contenant le XML généré
const XML_NODE_NAME = 'Code Restore Data1';

// Nœud contenant les données ERP complètes,
// notamment invoice.number = 10001403
const ERP_DATA_NODE_NAME = 'Microsoft SQL';

function readNode(nodeName) {
  try {
    return $(nodeName).first().json || {};
  } catch (error) {
    return {};
  }
}

function firstNonEmpty(values) {
  for (const value of values) {
    if (
      value !== undefined &&
      value !== null &&
      String(value).trim() !== ''
    ) {
      return String(value).trim();
    }
  }

  return '';
}

function sanitizeFileName(value) {
  return String(value)
    .trim()
    .replace(/[\\/:*?"<>|]/g, '_');
}

const xmlNodeData = readNode(XML_NODE_NAME);
const erpData = readNode(ERP_DATA_NODE_NAME);

return items.map((item) => {
  // ============================================================
  // XML
  // ============================================================

  const xml = firstNonEmpty([
    item.json.xml_content,
    item.json.xml,
    item.json.signed_xml,

    xmlNodeData.xml_content,
    xmlNodeData.xml,
    xmlNodeData.signed_xml,
  ]);

  if (!xml) {
    throw new Error(
      `XML introuvable dans le nœud "${XML_NODE_NAME}". ` +
      `Clés trouvées : ${JSON.stringify(Object.keys(xmlNodeData))}`
    );
  }

  // ============================================================
  // NUMÉRO DE FACTURE
  // ============================================================

  const documentMatch = xml.match(
    /<(?:[\w.-]+:)?DocumentIdentifier\b[^>]*>\s*([^<]+?)\s*<\/(?:[\w.-]+:)?DocumentIdentifier\s*>/i
  );

  let invoiceNumber = firstNonEmpty([
    documentMatch?.[1],

    // Item courant
    item.json.invoice_number,
    item.json.invoice?.number,
    item.json.data?.invoice?.number,

    item.json.document?.numero,
    item.json.facture?.numero,

    // Données ERP
    erpData.invoice_number,
    erpData.invoice?.number,
    erpData.data?.invoice?.number,

    erpData.document?.numero,
    erpData.facture?.numero,
  ]);

  let invoiceNumberSource = '';

  if (documentMatch?.[1]?.trim()) {
    invoiceNumberSource = 'DocumentIdentifier XML';
  } else if (
    item.json.invoice?.number ||
    item.json.invoice_number
  ) {
    invoiceNumberSource = 'item courant';
  } else if (
    erpData.invoice?.number ||
    erpData.data?.invoice?.number
  ) {
    invoiceNumberSource = ERP_DATA_NODE_NAME;
  }

  if (!invoiceNumber) {
    throw new Error(
      `Numéro de facture introuvable. ` +
      `Le XML contient un DocumentIdentifier vide et le nœud ` +
      `"${ERP_DATA_NODE_NAME}" ne contient pas invoice.number. ` +
      `Clés ERP trouvées : ${JSON.stringify(Object.keys(erpData))}`
    );
  }

  // ============================================================
  // FICHIER XML
  // ============================================================

  const safeInvoiceNumber =
    sanitizeFileName(invoiceNumber);

  const fileName =
    `${safeInvoiceNumber}_signed.xml`;

  return {
    json: {
      ...item.json,
      invoice_number: safeInvoiceNumber,
      file_name: fileName,
      invoice_number_source: invoiceNumberSource,
    },

    binary: {
      ...(item.binary || {}),

      data: {
        data: Buffer
          .from(xml, 'utf8')
          .toString('base64'),

        mimeType: 'application/xml',
        fileExtension: 'xml',
        fileName,
      },
    },
  };
});

return items.map(item => {
  return {
    json: {
      xml_content: item.json.xml
    }
  };
});

const rawSql = String($json.sql ?? '').trim();

if (!rawSql) {
  throw new Error('The generated SQL query is empty.');
}

if (!/^\s*SELECT\b/i.test(rawSql)) {
  throw new Error(
    `Only SELECT queries are allowed. Query starts with: ${rawSql.slice(0, 100)}`
  );
}

if (/\bRETURN\b/i.test(rawSql)) {
  throw new Error('The generated SQL contains an invalid RETURN statement.');
}

if (!/\bWHERE\b/i.test(rawSql)) {
  throw new Error(
    'Unsafe generated SQL: the WHERE clause is missing. Execution stopped before Microsoft SQL.'
  );
}

if (!/\bENT\.PINO\b/i.test(rawSql)) {
  throw new Error(
    'Unsafe generated SQL: the invoice filter ENT.PINO is missing.'
  );
}

if (!/\bENT\.TIERS\b/i.test(rawSql)) {
  throw new Error(
    'Unsafe generated SQL: the customer filter ENT.TIERS is missing.'
  );
}

let safeSql = rawSql;

// Add TOP (100) immediately after SELECT during testing.
if (!/^\s*SELECT\s+TOP\s*(?:\(\s*\d+\s*\)|\d+)/i.test(safeSql)) {
  safeSql = safeSql.replace(
    /^\s*SELECT\s+/i,
    'SELECT TOP (100) '
  );
}

return [
  {
    json: {
      ...$json,
      sql_original: rawSql,
      sql: safeSql,
      protection: {
        top_limit: 100,
        has_where: true,
        has_invoice_filter: true,
        has_customer_filter: true
      }
    }
  }
];

const source = $json;

/**
 * Nettoie les espaces ajoutés par les colonnes CHAR/NCHAR
 * de Microsoft SQL Server.
 */
function clean(value) {
  if (value === null || value === undefined) {
    return "";
  }

  return String(value).trim();
}

/**
 * Convertit une valeur vers un nombre valide.
 */
function number(value, defaultValue = 0) {
  const parsed = Number(value);

  return Number.isFinite(parsed)
    ? parsed
    : defaultValue;
}

/**
 * Arrondit les montants à 3 décimales.
 */
function money(value) {
  return Number(number(value).toFixed(3));
}

/**
 * Convertit :
 * 2026-06-29T00:00:00.000Z
 *
 * vers :
 * 29/06/2026
 */
function formatDate(value) {
  if (!value) {
    return "";
  }

  const text = String(value).trim();

  const isoMatch = text.match(/^(\d{4})-(\d{2})-(\d{2})/);

  if (isoMatch) {
    const [, year, month, day] = isoMatch;
    return `${day}/${month}/${year}`;
  }

  const frenchMatch = text.match(
    /^(\d{1,2})\/(\d{1,2})\/(\d{4})$/
  );

  if (frenchMatch) {
    const [, day, month, year] = frenchMatch;

    return [
      day.padStart(2, "0"),
      month.padStart(2, "0"),
      year
    ].join("/");
  }

  return text;
}

/**
 * Construit une adresse sans espaces inutiles.
 */
function buildAddress(...parts) {
  return parts
    .map(clean)
    .filter(Boolean)
    .join(", ");
}

const supplier = source.supplier || {};
const customer = source.customer || {};
const invoice = source.invoice || {};
const totals = source.totals || {};
const payment = source.payment || {};

const currency = clean(invoice.currency) || "EUR";

const supplierCountry = clean(supplier.country) || "FR";
const customerCountry = clean(customer.country) || "FR";

const supplierIdentifier =
  clean(supplier.vat_number) ||
  clean(supplier.siret);

const customerIdentifier =
  clean(customer.code) ||
  clean(customer.siret);

const lines = Array.isArray(source.lines)
  ? source.lines
  : [];

const mappedLines = lines.map((line, index) => {
  const quantity = number(line.quantity);
  const unitPrice = money(line.unit_price);
  const discount = money(line.discount);
  const lineTotalHt = money(line.line_total_ht);
  const taxRate = money(line.tax_rate);

  return {
    numero_ligne: index + 1,

    reference: clean(line.reference),

    designation:
      clean(line.designation) ||
      `Article ${index + 1}`,

    quantite: quantity,

    unite: "UNIT",

    prix_unitaire: unitPrice,

    remise: discount,

    taux_tva: taxRate,

    montant_ht: lineTotalHt,

    montant_tva: money(
      lineTotalHt * taxRate / 100
    ),

    montant_ttc: money(
      lineTotalHt +
      lineTotalHt * taxRate / 100
    ),

    code_tva: clean(line.vat_code),

    variante_article: clean(
      line.article_variant
    ),

    montant_brut: money(
      line.line_total_calculated ??
      quantity * unitPrice
    ),

    montant_remise: money(
      line.discount_amount
    )
  };
});

const sumLinesHt = money(
  mappedLines.reduce(
    (sum, line) => sum + number(line.montant_ht),
    0
  )
);

const sumLinesVat = money(
  mappedLines.reduce(
    (sum, line) => sum + number(line.montant_tva),
    0
  )
);

const totalHt = money(
  totals.total_ht ?? sumLinesHt
);

const totalTva = money(
  totals.vat_amount ?? sumLinesVat
);

const totalTtc = money(
  totals.total_ttc ??
  totalHt + totalTva
);

const taxableAmount = money(
  totals.taxable_amount ?? totalHt
);

const invoiceNumber = clean(invoice.number);

return {
  json: {
    document: {
      type_document: "Facture",
      code_type_document: "I-11",

      profil_pays:
        supplierCountry === "TN"
          ? "Tunisie"
          : "France",

      devise: currency,

      source: "erp_divalto",

      nombre_pages: 1,

      numero: invoiceNumber,

      date: formatDate(invoice.date),

      date_echeance: formatDate(
        invoice.due_date
      )
    },

    fournisseur: {
      nom: clean(supplier.name),

      identifiant: supplierIdentifier,

      type_identifiant:
        supplierCountry === "FR"
          ? "I-04"
          : "I-01",

      matricule_fiscal_ou_tva:
        clean(supplier.vat_number),

      siret: clean(supplier.siret),

      adresse:
        clean(supplier.full_address) ||
        buildAddress(
          supplier.address,
          supplier.address2,
          supplier.postal_code,
          supplier.city
        ),

      pays: supplierCountry,

      telephone: clean(supplier.phone),

      fax: clean(supplier.fax),

      email: clean(supplier.email),

      site_web: clean(supplier.website)
    },

    client: {
      code: clean(customer.code),

      nom: clean(customer.name),

      identifiant: customerIdentifier,

      type_identifiant:
        customerCountry === "FR"
          ? "I-04"
          : "I-01",

      matricule_fiscal_ou_tva: "",

      siret: clean(customer.siret),

      adresse:
        clean(customer.full_address) ||
        buildAddress(
          customer.address,
          customer.address2,
          customer.postal_code,
          customer.city
        ),

      pays: customerCountry,

      ville: clean(customer.city),

      code_postal: clean(
        customer.postal_code
      ),

      telephone: clean(customer.phone),

      fax: clean(customer.fax),

      email: clean(customer.email)
    },

    facture: {
      numero: invoiceNumber,

      date: formatDate(invoice.date),

      date_echeance: formatDate(
        invoice.due_date
      ),

      devise: currency,

      mode_paiement:
        clean(payment.description) ||
        clean(payment.code),

      code_paiement: clean(payment.code),

      iban: clean(payment.iban),

      bic: clean(payment.bic)
    },

    lignes_facture: mappedLines,

    totaux: {
      base_tva: taxableAmount,

      montant_imposable: taxableAmount,

      total_ht: totalHt,

      total_tva: totalTva,

      montant_tva: totalTva,

      total_ttc: totalTtc,

      net_a_payer: money(
        totals.net_amount ?? totalTtc
      ),

      montant_brut: money(
        totals.gross_amount ?? totalTtc
      ),

      frais_port_non_soumis: money(
        totals.shipping_not_taxed
      ),

      frais_port_soumis: money(
        totals.shipping_taxed
      ),

      frais_emballage: money(
        totals.packaging_cost
      ),

      droit_timbre: 0
    },

    paiement: {
      code_banque: clean(
        payment.bank_code
      ),

      type: number(payment.type),

      code: clean(payment.code),

      description: clean(
        payment.description
      ),

      iban: clean(payment.iban),

      bic: clean(payment.bic)
    },

    entreprise: {
      code: clean(
        source.company?.code
      )
    },

    controle_validation: {
      peut_generer_teif:
        Boolean(invoiceNumber) &&
        Boolean(clean(supplier.name)) &&
        Boolean(clean(customer.name)) &&
        mappedLines.length > 0,

      nombre_lignes: mappedLines.length,

      somme_lignes_ht: sumLinesHt,

      ecart_lignes_total_ht: money(
        totalHt - sumLinesHt
      ),

      source: "erp_divalto"
    }
  }
};
